async function save(data) {
  try {
    await fetch('/api/notes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    })
    alert('Saved!')
  } catch (err) {
    alert('Failed: ' + err.message)
  }
}
